#include "cinderwatch/packet/packet.h"
namespace cinderwatch::packet{using namespace core;Result<PcapHeader> parse_pcap_header(ByteReader&br){auto m=br.u32();if(!m)return m.st;PcapHeader h;h.magic=m.value();if(h.magic==0xa1b2c3d4)h.little=false;else if(h.magic==0xd4c3b2a1)h.little=true;else return Status::error(Code::Malformed,"bad pcap magic");br.endian(h.little);auto a=br.u16(),b=br.u16();br.skip(8);auto sl=br.u32(),nw=br.u32();if(!nw)return nw.st;h.major=a.value();h.minor=b.value();h.snaplen=sl.value();h.network=nw.value();return h;}Result<Record> parse_record(ByteReader&br){Record r;r.off=br.pos();auto a=br.u32(),b=br.u32(),c=br.u32(),d=br.u32();if(!d)return d.st;r.sec=a.value();r.usec=b.value();r.incl=c.value();r.orig=d.value();if(r.incl>67108864)return Status::error(Code::Range,"record large",r.off);return r;}Result<Ethernet> parse_ethernet(const uint8_t*d,size_t n){ByteReader br(d,n,false);if(n<14)return Status::error(Code::Range,"short ethernet");Ethernet e;for(int i=0;i<6;i++)e.dst[i]=br.u8().value();for(int i=0;i<6;i++)e.src[i]=br.u8().value();e.type=br.u16().value();auto p=br.bytes(br.remaining());if(!p)return p.st;e.payload=p.value();return e;}Result<IPv4Header> parse_ipv4_packet(const uint8_t*d,size_t n){ByteReader br(d,n,false);auto v=br.u8();if(!v)return v.st;if((v.value()>>4)!=4)return Status::error(Code::Malformed,"not ipv4");IPv4Header h;h.ihl=(v.value()&15)*4;if(h.ihl<20||h.ihl>n)return Status::error(Code::Malformed,"bad ihl");br.skip(1);h.total=br.u16().value();br.skip(5);h.ttl=br.u8().value();h.proto=br.u8().value();br.skip(2);h.src=IPv4{br.u32().value()};h.dst=IPv4{br.u32().value()};if(h.ihl>20)br.skip(h.ihl-20);size_t plen=h.total>=h.ihl&&h.total<=n?h.total-h.ihl:br.remaining();auto p=br.bytes(std::min(plen,br.remaining()));if(!p)return p.st;h.payload=p.value();return h;}Result<Tcp> parse_tcp(const uint8_t*d,size_t n){ByteReader br(d,n,false);if(n<20)return Status::error(Code::Range,"short tcp");Tcp t;t.sp=br.u16().value();t.dp=br.u16().value();t.seq=br.u32().value();t.ack=br.u32().value();auto o=br.u8().value();t.off=(o>>4)*4;t.flags=((o&1)<<8)|br.u8().value();br.skip(4);if(t.off<20||t.off>n)return Status::error(Code::Malformed,"bad tcp offset");if(t.off>20)br.skip(t.off-20);auto p=br.bytes(br.remaining());if(!p)return p.st;t.payload=p.value();return t;}Result<Udp> parse_udp(const uint8_t*d,size_t n){ByteReader br(d,n,false);if(n<8)return Status::error(Code::Range,"short udp");Udp u;u.sp=br.u16().value();u.dp=br.u16().value();u.len=br.u16().value();br.skip(2);if(u.len<8)return Status::error(Code::Malformed,"bad udp length");auto p=br.bytes(std::min<size_t>(u.len-8,br.remaining()));if(!p)return p.st;u.payload=p.value();return u;}Result<std::string> parse_dns_name(const uint8_t*d,size_t n,size_t&off,std::vector<size_t>&seen){std::string name;size_t p=off,depth=0;bool jump=false;while(p<n){if(depth++>64)return Status::error(Code::Malformed,"dns pointer depth",p);uint8_t len=d[p++];if((len&0xc0)==0xc0){if(p>=n)return Status::error(Code::Range,"short dns pointer",p);size_t ptr=((len&0x3f)<<8)|d[p++];if(ptr>=n)return Status::error(Code::Range,"dns pointer range",p);if(std::find(seen.begin(),seen.end(),ptr)!=seen.end())return Status::error(Code::Malformed,"dns pointer loop",ptr);seen.push_back(ptr);if(!jump){off=p;jump=true;}p=ptr;continue;}if((len&0xc0)!=0)return Status::error(Code::Malformed,"dns label flags",p-1);if(!len){if(!jump)off=p;return name;}if(len>63||p+len>n)return Status::error(Code::Range,"short dns label",p);if(!name.empty())name+='.';for(size_t i=0;i<len;i++){unsigned char c=d[p+i];name+=std::isalnum(c)||c=='-'?char(std::tolower(c)):'x';}p+=len;}return Status::error(Code::Range,"unterminated dns name",p);}static Result<DnsRR> rr(const uint8_t*d,size_t n,size_t&off){DnsRR r;std::vector<size_t>v;auto nm=parse_dns_name(d,n,off,v);if(!nm)return nm.st;r.name=nm.value();if(off+10>n)return Status::error(Code::Range,"short dns rr",off);ByteReader br(d+off,n-off,false);r.type=br.u16().value();r.klass=br.u16().value();r.ttl=br.u32().value();auto len=br.u16().value();off+=10;if(off+len>n)return Status::error(Code::Range,"short rdata",off);r.rdata.assign(d+off,d+off+len);if(r.type==1&&len==4)r.text=IPv4{(uint32_t(r.rdata[0])<<24)|(uint32_t(r.rdata[1])<<16)|(uint32_t(r.rdata[2])<<8)|r.rdata[3]}.text();off+=len;return r;}Result<Dns> parse_dns(const uint8_t*d,size_t n){ByteReader br(d,n,false);if(n<12)return Status::error(Code::Range,"short dns");Dns x;x.id=br.u16().value();x.flags=br.u16().value();auto qd=br.u16().value(),an=br.u16().value(),ns=br.u16().value(),ar=br.u16().value();size_t off=12;for(size_t i=0;i<qd&&i<256;i++){std::vector<size_t>v;auto nm=parse_dns_name(d,n,off,v);if(!nm){x.diagnostics.push_back({Severity::Medium,"dns.name",nm.st.msg,{"",1,1,nm.st.off}});return x;}if(off+4>n)return Status::error(Code::Range,"short question",off);ByteReader qb(d+off,n-off,false);x.q.push_back({nm.value(),qb.u16().value(),qb.u16().value()});off+=4;}auto read=[&](std::vector<DnsRR>&out,size_t c){for(size_t i=0;i<c&&i<512;i++){auto r=rr(d,n,off);if(!r){x.diagnostics.push_back({Severity::Medium,"dns.rr",r.st.msg,{"",1,1,r.st.off}});return;}out.push_back(r.value());}};read(x.a,an);read(x.auth,ns);read(x.add,ar);return x;}Flow flow_key(const PacketSummary&s){uint32_t a=s.src.v,b=s.dst.v;uint16_t ap=s.sp,bp=s.dp;if(std::tie(b,bp)<std::tie(a,ap)){std::swap(a,b);std::swap(ap,bp);}return{a,b,ap,bp,s.proto};}Analysis analyze_bytes(const std::vector<uint8_t>&b){Analysis a;ByteReader br(b.data(),b.size(),true);auto h=parse_pcap_header(br);if(!h){a.report.diagnostics.push_back({Severity::High,"pcap",h.st.msg,{"",1,1,h.st.off}});return a;}a.header=h.value();size_t idx=0;while(br.remaining()>=16){auto rec=parse_record(br);if(!rec){a.report.diagnostics.push_back({Severity::Medium,"pcap.record",rec.st.msg,{"",1,1,rec.st.off}});break;}if(!br.can(rec.value().incl)){a.report.diagnostics.push_back({Severity::High,"pcap.record","record exceeds file",{"",1,1,br.pos()}});break;}auto bytes=br.bytes(rec.value().incl).value();a.counters["records"]++;auto e=parse_ethernet(bytes.data(),bytes.size());if(!e)continue;if(e.value().type!=0x0800)continue;auto ip=parse_ipv4_packet(e.value().payload.data(),e.value().payload.size());if(!ip)continue;PacketSummary s;s.index=idx++;s.src=ip.value().src;s.dst=ip.value().dst;s.proto=ip.value().proto;if(s.proto==6){auto t=parse_tcp(ip.value().payload.data(),ip.value().payload.size());if(t){s.sp=t.value().sp;s.dp=t.value().dp;if(s.sp==53||s.dp==53){auto d=parse_dns(t.value().payload.data(),t.value().payload.size());if(d)for(auto&q:d.value().q)s.dns.push_back(q.name);}}}else if(s.proto==17){auto u=parse_udp(ip.value().payload.data(),ip.value().payload.size());if(u){s.sp=u.value().sp;s.dp=u.value().dp;if(s.sp==53||s.dp==53){auto d=parse_dns(u.value().payload.data(),u.value().payload.size());if(d)for(auto&q:d.value().q)s.dns.push_back(q.name);}}}if(ip.value().ttl<=1)s.findings.push_back({Severity::Low,"packet","Low TTL","Packet TTL is unusually low"});a.packets.push_back(s);}return a;}Analysis analyze_file(const std::string&p){auto a=analyze_bytes(read_bytes(p));a.report.subject=p;return a;}std::string text(const Analysis&a){std::ostringstream o;o<<"Packets: "<<a.packets.size()<<"\n";for(auto&kv:a.counters)o<<kv.first<<": "<<kv.second<<"\n";for(auto&p:a.packets){o<<"#"<<p.index<<" "<<p.src.text()<<":"<<p.sp<<" -> "<<p.dst.text()<<":"<<p.dp<<" proto "<<int(p.proto);for(auto&d:p.dns)o<<" dns="<<d;o<<"\n";}o<<report_text(a.report);return o.str();}std::string json(const Analysis&a){std::ostringstream o;o<<"{\"packets\":[";bool f=true;for(auto&p:a.packets){if(!f)o<<",";f=false;o<<"{\"src\":\""<<p.src.text()<<"\",\"dst\":\""<<p.dst.text()<<"\",\"protocol\":"<<int(p.proto)<<"}";}o<<"],\"report\":"<<report_json(a.report)<<"}";return o.str();}}
